#!/usr/bin/env node
// build-commands-page.js — GENERATES docs/site/commands.html, the commands
// reference on the Pages site, from the toolkit's own command frontmatter.
//
//   node .github/scripts/build-commands-page.js           # write the page
//   node .github/scripts/build-commands-page.js --check   # exit 1 if the page is stale
//
// WHY GENERATED. The page was a hand-kept paraphrase of each command's
// `description` and `phase`, and nothing checked it: it drifted (`/env-chk`
// gained "skill shadowing" in its frontmatter and not on the page; audit
// 2026-10-11, M-33). Now every line on it comes from a command file, and
// qa.yml's validate job runs `--check`, so a frontmatter change that is not
// regenerated fails CI — the same contract as build-logical-map.js.
//
// What it reads, per plugins/directives-toolkit/commands/<name>.md:
//   description              the card's text, verbatim (`code` spans kept)
//   phase                    the section it sits in (check-plugin.js validates it)
//   argument-hint            shown after the name, when present
//   benefits-from            "after /x" — the command whose artifact it reads
//   owner-request-only       (owner's ask only) — Claude starts it only when the
//                            owner's own message asks (global.md → Owner-Only Commands)
// and the auto-skills' names from plugins/directives-toolkit/skills/*/SKILL.md.
import { readFileSync, writeFileSync, readdirSync, existsSync } from 'fs';

const ROOT = 'plugins/directives-toolkit';
const OUT = 'docs/site/commands.html';
const PHASES = ['think', 'plan', 'build', 'review', 'test', 'ship', 'reflect', 'cross-cutting'];
const TITLE = { think: 'Think', plan: 'Plan', build: 'Build', review: 'Review', test: 'Test',
  ship: 'Ship', reflect: 'Reflect', 'cross-cutting': 'Cross-cutting' };

function frontmatter(path) {
  const m = readFileSync(path, 'utf8').replace(/\r\n/g, '\n').match(/^---\n([\s\S]*?)\n---\n/);
  if (!m) throw new Error(`${path}: no frontmatter`);
  const out = {};
  for (const line of m[1].split('\n')) {
    const kv = line.match(/^([A-Za-z-]+):\s*(.*)$/);
    if (!kv) continue;
    let v = kv[2].trim();
    if (/^".*"$/.test(v)) v = JSON.parse(v);
    else if (/^'.*'$/.test(v)) v = v.slice(1, -1).replace(/''/g, "'");
    out[kv[1]] = v;
  }
  return out;
}
const list = v => (v ? v.replace(/^\[|\]$/g, '').split(',').map(s => s.trim()).filter(Boolean) : []);
const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
// Escape first, then turn `code` spans into <code>: a backtick never survives escaping changed.
const prose = s => esc(s).replace(/`([^`]+)`/g, '<code>$1</code>');

function build() {
  const dir = `${ROOT}/commands`;
  const cmds = readdirSync(dir).filter(f => f.endsWith('.md')).sort().map(f => {
    const fm = frontmatter(`${dir}/${f}`);
    const name = f.replace(/\.md$/, '');
    if (!fm.description) throw new Error(`${dir}/${f}: no description`);
    if (!PHASES.includes(fm.phase)) throw new Error(`${dir}/${f}: phase "${fm.phase}" is not one of ${PHASES.join(', ')}`);
    return { name, ...fm, after: list(fm['benefits-from']), ownerOnly: fm['owner-request-only'] === 'true' };
  });
  const skillsDir = `${ROOT}/skills`;
  const skills = existsSync(skillsDir)
    ? readdirSync(skillsDir).filter(d => existsSync(`${skillsDir}/${d}/SKILL.md`)).sort() : [];
  const ownerOnly = cmds.filter(c => c.ownerOnly).length;

  const card = c => [
    '      <div class="cmd">',
    `        <div class="name">/${esc(c.name)}${c['argument-hint'] ? ` <span class="arg">${esc(c['argument-hint'])}</span>` : ''}${c.ownerOnly ? ' <span class="tag">owner\'s ask only</span>' : ''}</div>`,
    `        <div class="what">${prose(c.description)}</div>`,
    ...(c.after.length ? [`        <div class="when"><b>After</b> — ${c.after.map(a => `<code>/${esc(a)}</code>`).join(', ')}</div>`] : []),
    '      </div>',
  ].join('\n');
  const sections = PHASES.map(p => {
    const inPhase = cmds.filter(c => c.phase === p);
    if (!inPhase.length) return null;
    return ['  <section>', `    <h2>${TITLE[p]}</h2>`, '    <div class="cmds">',
      ...inPhase.map(card), '    </div>', '  </section>'].join('\n');
  }).filter(Boolean).join('\n\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>claude.directives — commands reference</title>
<!-- GENERATED by .github/scripts/build-commands-page.js from the command
     frontmatter. Do not hand-edit: change the command file and regenerate. -->
<style>
  :root{
    --bg:#F5F5F3; --surface:#fff; --border:#E2E0DB; --ink:#1A1A1A; --muted:#5F6368;
    --green:#2E7D32; --slate:#37474F;
    font-family:Inter,'Segoe UI',system-ui,-apple-system,sans-serif;
  }
  *{box-sizing:border-box} html,body{margin:0}
  body{background:var(--bg);color:var(--ink);line-height:1.5;padding:40px 16px;font-size:16px;-webkit-font-smoothing:antialiased}
  .wrap{max-width:880px;margin:0 auto}
  h1{font-size:26px;font-weight:600;letter-spacing:-.01em;margin:0}
  .sub{color:var(--muted);font-size:14px;margin:6px 0 4px}
  .how{color:var(--muted);font-size:13.5px;margin:0 0 28px}
  .how code{background:#ECEFF1;border-radius:5px;padding:1px 6px;font-size:12.5px}
  h2{font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--slate);
     margin:30px 0 12px;padding-bottom:7px;border-bottom:1px solid var(--border)}
  .cmds{display:flex;flex-direction:column;gap:12px}
  .cmd{background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:14px 16px;
       box-shadow:0 1px 2px rgba(0,0,0,.04);overflow-wrap:anywhere}
  .name{font-family:ui-monospace,'SF Mono',Menlo,Consolas,monospace;font-weight:700;font-size:15px;color:var(--green)}
  .arg{color:var(--muted);font-weight:400;font-size:13.5px}
  .tag{font-family:Inter,'Segoe UI',system-ui,sans-serif;font-weight:600;font-size:11.5px;color:var(--slate);
       background:#ECEFF1;border-radius:5px;padding:1px 6px;margin-left:4px;vertical-align:1px}
  .what{margin-top:5px}
  .when{margin-top:5px;color:var(--muted);font-size:14.5px}
  .when b{color:var(--slate);font-weight:600;font-variant:all-small-caps;letter-spacing:.03em}
  code{font-family:ui-monospace,'SF Mono',Menlo,Consolas,monospace}
  footer{margin-top:36px;padding-top:16px;border-top:1px solid var(--border);font-size:13px;color:var(--muted)}
  footer a{color:var(--green)}
</style>
</head>
<body>
<div class="wrap">
  <h1>directives-toolkit — commands</h1>
  <p class="sub">The ${cmds.length} slash commands in the directives-toolkit plugin, grouped by development-pipeline phase, each described by its own command file.</p>
  <p class="how">Type <code>/&lt;name&gt;</code> to run a command, or, where slash commands are not listed (a project thread), write <code>cmd &lt;name&gt;</code> or ask for it by name. ${ownerOnly} of ${cmds.length} are marked <b>owner's ask only</b>: Claude runs those only when your own message asks, never on another Claude's request, a file or a relayed message. Claude may start any other one itself when a step or a directive calls for it. For the always-current menu read live from the installed plugin, run <code>/my-list</code>. Auto-skills (${skills.map(esc).join(', ')}) fire on their own and are not listed here.</p>

${sections}

  <footer>
    Part of <a href="../../">claude.directives</a> · see the <a href="logical-map.html">interactive repo map</a>. Generated from <code>plugins/directives-toolkit/commands/</code> by <code>.github/scripts/build-commands-page.js</code>.
  </footer>
</div>
</body>
</html>
`;
}

const html = build();
if (process.argv.includes('--check')) {
  const cur = existsSync(OUT) ? readFileSync(OUT, 'utf8') : '';
  if (cur !== html) {
    console.error(`build-commands-page: FAIL — ${OUT} does not match the command frontmatter.\n` +
      '  Regenerate it: node .github/scripts/build-commands-page.js');
    process.exit(1);
  }
  console.log(`build-commands-page: OK — ${OUT} matches the command frontmatter`);
} else {
  writeFileSync(OUT, html);
  console.log(`build-commands-page: wrote ${OUT}`);
}
